/**
 * Weekly streaks, badges and quotas (PRD §habit layer, monetization).
 * Weeks start on Monday (local time). Streaks are weekly — never daily — to avoid guilt.
 */

export const BADGE_THRESHOLDS = [1, 5, 10, 25, 50, 100] as const;
export const FREE_CONVERSIONS_PER_MONTH = 5;
export const PRO_FAIR_USE_PER_MONTH = 150;

/** Monday 00:00 local of the week containing `d`, as YYYY-MM-DD. */
export function weekKey(d: Date): string {
  const day = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const dow = (day.getDay() + 6) % 7; // Mon=0 … Sun=6
  day.setDate(day.getDate() - dow);
  return isoDate(day);
}

export function isoDate(d: Date): string {
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${m}-${dd}`;
}

export function monthKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function addWeeks(key: string, n: number): string {
  const [y, m, d] = key.split('-').map(Number) as [number, number, number];
  const dt = new Date(y, m - 1, d);
  dt.setDate(dt.getDate() + n * 7);
  return isoDate(dt);
}

export interface StreakInput {
  /** Dates of completed looks (abandoned sessions must not be included). */
  completions: Date[];
  /** Her weekly goal N (1–7). */
  weeklyGoal: number;
  /** Week keys where a freeze was used (max one per calendar month). */
  frozenWeeks: string[];
  now: Date;
}

export interface StreakState {
  /** Consecutive goal-met weeks, counting the current week only if already met. */
  streakWeeks: number;
  thisWeekCount: number;
  thisWeekMet: boolean;
  lifetimeLooks: number;
  /** Days left in the current week including today. */
  daysLeftInWeek: number;
  /** Nudge once when goal unmet with exactly 2 days left. */
  shouldNudge: boolean;
}

export function computeStreak(input: StreakInput): StreakState {
  const goal = Math.min(7, Math.max(1, Math.round(input.weeklyGoal)));
  const counts = new Map<string, number>();
  for (const c of input.completions) {
    const k = weekKey(c);
    counts.set(k, (counts.get(k) ?? 0) + 1);
  }
  const frozen = new Set(input.frozenWeeks);
  const current = weekKey(input.now);
  const thisWeekCount = counts.get(current) ?? 0;
  const thisWeekMet = thisWeekCount >= goal;

  let streak = thisWeekMet ? 1 : 0;
  let k = addWeeks(current, -1);
  // Walk back through previous weeks while each is met or frozen.
  for (let i = 0; i < 520; i++) {
    const met = (counts.get(k) ?? 0) >= goal;
    if (met) streak++;
    else if (!frozen.has(k)) break;
    k = addWeeks(k, -1);
  }
  const dow = (input.now.getDay() + 6) % 7;
  const daysLeftInWeek = 7 - dow;
  return {
    streakWeeks: streak,
    thisWeekCount,
    thisWeekMet,
    lifetimeLooks: input.completions.length,
    daysLeftInWeek,
    shouldNudge: !thisWeekMet && daysLeftInWeek === 2,
  };
}

/** One free freeze per calendar month. */
export function canUseFreeze(frozenWeeks: string[], now: Date): boolean {
  const m = monthKey(now);
  return !frozenWeeks.some((w) => w.startsWith(m));
}

export function earnedBadges(lifetimeLooks: number): number[] {
  return BADGE_THRESHOLDS.filter((t) => lifetimeLooks >= t);
}

export function nextBadge(lifetimeLooks: number): number | null {
  return BADGE_THRESHOLDS.find((t) => lifetimeLooks < t) ?? null;
}

export interface QuotaCheck {
  allowed: boolean;
  used: number;
  limit: number;
  remaining: number;
  /** First day of next month, YYYY-MM-DD. */
  refreshesOn: string;
}

/**
 * Can she start a NEW AI conversion? Cache hits never count (callers skip this check).
 * The same rule runs on the server before any paid AI call.
 */
export function checkConversionQuota(usedThisMonth: number, isPro: boolean, now: Date): QuotaCheck {
  const limit = isPro ? PRO_FAIR_USE_PER_MONTH : FREE_CONVERSIONS_PER_MONTH;
  const next = new Date(now.getFullYear(), now.getMonth() + 1, 1);
  return {
    allowed: usedThisMonth < limit,
    used: usedThisMonth,
    limit,
    remaining: Math.max(0, limit - usedThisMonth),
    refreshesOn: isoDate(next),
  };
}
